-- PDCA Compliance · /dashboard/ehs/empresa (aud8 90/95) · RD-95: "?" nas colunas, no filtro de grupo e nas ações.
-- ADITIVA: só textos de ajuda novos (erp_ajuda_campo). Não cria/altera tabela, RLS, policy, grant ou dado de cliente.
-- Idempotente (ON CONFLICT (chave) DO NOTHING).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, v.rota, 'compliance', 'publicado'
FROM (VALUES
 ('compliance.empresa.filtro_grupo', 'Documentos da Empresa', 'Grupo', 'Toque em um grupo (Ambiental, eSocial, Fiscal, Jurídico, Saúde, Segurança…) para ver só os documentos daquela área, ou "Todos os grupos".', 'Organiza a papelada da empresa por área de conformidade, para você conferir rapidamente o que falta em cada frente.', 'Tocar em "Segurança" para revisar PGR, PCMSO e NR-1 juntos.', 'Achar que um documento sumiu porque está com outro grupo selecionado: volte a "Todos os grupos".', 1, '/dashboard/ehs/empresa'),
 ('compliance.empresa.documento', 'Documentos da Empresa', 'Documento', 'Nada a preencher: é o nome do documento obrigatório da empresa (eSocial, FGTS, CNDT, PGR, PCMSO, NR-1…).', 'Lista o que a empresa precisa manter em dia perante órgãos e clientes; cada linha é um tipo de documento.', 'Linha "CNDT — Certidão Negativa de Débitos Trabalhistas".', 'Confundir o tipo de documento com o arquivo em si: o arquivo é anexado na coluna Arquivo.', 2, '/dashboard/ehs/empresa'),
 ('compliance.empresa.tipo', 'Documentos da Empresa', 'Tipo', 'Nada a preencher: o grupo/área a que o documento pertence (Fiscal, Jurídico, Saúde…).', 'Deixa claro a qual frente de conformidade o documento responde e combina com o filtro de grupo.', 'Documento "PGR" com Tipo "Segurança".', 'Procurar um documento no grupo errado por não olhar o Tipo.', 3, '/dashboard/ehs/empresa'),
 ('compliance.empresa.empresa', 'Documentos da Empresa', 'Empresa', 'Nada a preencher: mostra a qual empresa do grupo o documento pertence.', 'Quando você vê mais de uma empresa, separa a papelada de cada uma para não misturar.', 'Documento "FGTS" da empresa "Construtora Alfa".', 'Anexar o arquivo na empresa errada: confira a coluna Empresa antes do upload.', 4, '/dashboard/ehs/empresa'),
 ('compliance.empresa.status', 'Documentos da Empresa', 'Status', 'Nada a preencher: a situação do documento (em dia, a vencer, vencido ou pendente de envio).', 'É o semáforo da conformidade: vermelho/pendente pede ação, verde está em dia.', 'Status "Vencido" num PCMSO cuja validade já passou.', 'Ignorar um status "A vencer": ele avisa antes de virar vencido, para dar tempo de renovar.', 5, '/dashboard/ehs/empresa'),
 ('compliance.empresa.validade', 'Documentos da Empresa', 'Validade', 'Nada a preencher: a data até a qual o documento vale (quando se aplica).', 'Antecipa renovações: o sistema usa essa data para calcular "a vencer" e "vencido".', 'Validade 31/12/2026 numa certidão anual.', 'Supor que documento sem validade nunca vence: alguns exigem reemissão periódica mesmo sem data fixa.', 6, '/dashboard/ehs/empresa'),
 ('compliance.empresa.arquivo', 'Documentos da Empresa', 'Arquivo', 'Nada a preencher: indica se há um arquivo (PDF) anexado para aquele documento.', 'Guarda a prova digital do documento, pronta para baixar numa auditoria ou envio ao cliente.', 'Linha com arquivo anexado mostra o botão Baixar.', 'Marcar um documento como em dia sem anexar o arquivo: sem o PDF não há comprovação.', 7, '/dashboard/ehs/empresa'),
 ('compliance.empresa.acoes', 'Documentos da Empresa', 'Ações', 'Nada a preencher: os botões por linha — Upload anexa/atualiza o PDF do documento; Baixar abre o arquivo já anexado.', 'Mantém a papelada da empresa comprovada e acessível: Upload sobe a versão nova, Baixar recupera a atual.', 'Clicar em Upload para anexar o PGR do ano e depois Baixar para conferir.', 'Fazer Upload no tipo errado: confira a linha (Documento/Tipo) antes de anexar.', 8, '/dashboard/ehs/empresa')
) AS v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem, rota)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
